import{_ as a,C as s,o as i,c as o,E as n,a2 as r}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse(`{"title":"The User Clicked ‘Always Allow.’ What Did the System Actually Save?","description":"","frontmatter":{"title":"The User Clicked ‘Always Allow.’ What Did the System Actually Save?","date":"2026-08-12","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"How should an approval architecture unify decision vocabulary without conflating a user's requested consent scope with the policy state that was actually applied?","summary":"A shared approval type can carry user intent without proving that policy took effect at the same scope. Governed approval records need both the requested decision and the effective outcome.","sources":"https://github.com/openai/codex/commit/67afc7967463282af932be1984df9e16cc55ed99; research/analysis/Q-20260812-02-decision-intent-effective-policy.md; research/reading/Q-20260812-02-reviewdecision-mcp-policy-amendment.md","item_id":"Q-20260812-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-12-consent-effective-policy.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-08-12-consent-effective-policy.md","filePath":"en/industry/2026-08-12-consent-effective-policy.md","lastUpdated":1786537128000}`),c={name:"en/industry/2026-08-12-consent-effective-policy.md"};function l(d,e,h,p,u,m){const t=s("ArticleCover");return i(),o("div",null,[n(t,{image:"/assets/covers/daily-2026-08-12-consent-effective-policy.png",kicker:"Industry Architecture · Daily Research",title:"The User Clicked ‘Always Allow.’ What Did the System Actually Save?",summary:"A shared approval type can carry user intent without proving that policy took effect at the same scope. Governed approval records need both the requested decision and the effective outcome.",version:"Q-20260812-02",status:"Daily Runtime V5 · 2026-08-12",languageHref:"/zh/industry/2026-08-12-consent-effective-policy",languageLabel:"中文"}),e[0]||(e[0]=r(`<h1 id="the-user-clicked-always-allow-what-did-the-system-actually-save" tabindex="-1">The User Clicked “Always Allow.” What Did the System Actually Save? <a class="header-anchor" href="#the-user-clicked-always-allow-what-did-the-system-actually-save" aria-label="Permalink to &quot;The User Clicked “Always Allow.” What Did the System Actually Save?&quot;">​</a></h1><p>An approval UI offers three choices: allow once, allow for this session, and always allow. The user chooses the third option, the tool runs, and the audit trail retains one value: <code>ApprovedMcpPolicyAmendment</code>.</p><p>That value establishes cross-session intent. It does not yet tell an operator whether policy was written, what future calls it matches, or whether an unavailable persistence key turned the result into session-only memory.</p><p>The selected <a href="https://github.com/openai/codex/commit/67afc7967463282af932be1984df9e16cc55ed99" target="_blank" rel="noreferrer">OpenAI Codex change</a> moves MCP approvals onto shared <code>ReviewDecision</code>, preserves current-call, session and persistent-policy outcomes, and rejects the MCP-only decision fail-closed if it reaches unrelated Shell, Command or Network approval paths. It solves fragmented vocabulary while exposing a second boundary: <strong>a shared decision value is control intent, not a receipt proving effective policy.</strong></p><h2 id="always-allow-passes-through-three-gates" tabindex="-1">“Always allow” passes through three gates <a class="header-anchor" href="#always-allow-passes-through-three-gates" aria-label="Permalink to &quot;“Always allow” passes through three gates&quot;">​</a></h2><p>The path from user choice to durable policy contains at least three different semantics:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Question</th><th>What can change the answer</th></tr></thead><tbody><tr><td>Requested decision</td><td>What scope did the user request?</td><td>UI choice, Guardian, or another decision source</td></tr><tr><td>Normalized decision</td><td>What does this domain and approval mode permit?</td><td>Domain legality, mode constraints, enterprise policy</td></tr><tr><td>Effective policy</td><td>What was actually stored or remembered?</td><td>Persistent key, session key, storage outcome and revision</td></tr></tbody></table><p>The source shows that approval-mode normalization may narrow session or persistent scope to ordinary <code>Approved</code>; a missing persistent key may also fall back to session memory. “The user selected always allow” and “the system stored cross-session policy” therefore require separate evidence.</p><h2 id="shared-types-unify-language-not-authority" tabindex="-1">Shared types unify language, not authority <a class="header-anchor" href="#shared-types-unify-language-not-authority" aria-label="Permalink to &quot;Shared types unify language, not authority&quot;">​</a></h2><p>Private enums keep local meaning obvious but force UI, hooks, Guardian and audit layers to translate every tool family. Shared <code>ReviewDecision</code> provides a common control vocabulary while retaining rejection reasons, timeout, cancellation and approval scope.</p><p>A variant existing in the shared sum type does not authorize every consumer to interpret it. When an MCP policy decision reaches command execution, the safe result is not “it starts with Approved”; it is a semantic-domain mismatch and a decline.</p><p>The protocol needs two forms of stability at once: common transport vocabulary and a domain-specific legal-value set at every adapter. The first without the second turns interoperability into authority leakage.</p><h2 id="an-audit-record-needs-two-answers" tabindex="-1">An audit record needs two answers <a class="header-anchor" href="#an-audit-record-needs-two-answers" aria-label="Permalink to &quot;An audit record needs two answers&quot;">​</a></h2><p>Where normalization, downgrade or asynchronous persistence can occur, a single <code>decision</code> field is insufficient:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">requested_decision</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">approved_mcp_policy_amendment</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">effective_scope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">session</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">normalization_reason</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">persistent_key_unavailable</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">policy_revision</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">persistence_outcome</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">downgraded</span></span></code></pre></div><p>The first two fields separate intent from realized capability; the reason explains the divergence; the revision or durable acknowledgement establishes what the policy store actually did.</p><p>This is not logging for its own sake. It prevents both a temporary approval being reported as persistent policy and a user believing policy was saved only to be prompted again in the next session.</p><h2 id="fail-closed-matters-most-at-semantic-mismatches" tabindex="-1">Fail-closed matters most at semantic mismatches <a class="header-anchor" href="#fail-closed-matters-most-at-semantic-mismatches" aria-label="Permalink to &quot;Fail-closed matters most at semantic mismatches&quot;">​</a></h2><p>Conventional checks ask whether a decision is Allow or Deny. A shared control plane has another failure mode: an Allow that is meaningful in domain A arrives at domain B and is mistaken for B&#39;s own Allow.</p><p>Adapters should therefore validate actor, resource and effect—not string prefixes. Unknown variants, MCP-only variants in generic tool paths, and missing policy keys need explicit rejection or downgrade facts. Denial, timeout and cancellation should also remain separate audit outcomes; they imply different retry and responsibility semantics even when none authorizes execution.</p><h2 id="dual-records-are-not-a-tax-on-every-approval" tabindex="-1">Dual records are not a tax on every approval <a class="header-anchor" href="#dual-records-are-not-a-tax-on-every-approval" aria-label="Permalink to &quot;Dual records are not a tax on every approval&quot;">​</a></h2><p>For one-shot synchronous approval with no possible scope conversion, requested and effective decisions may be identical. If every consumer knows the domain and persistence completes in the same transaction, one decision can be adequate.</p><p>Dual records become necessary when at least one divergence point exists: policy can narrow scope; persistence can be asynchronous, fail or downgrade; domains share one type; or audit must explain cross-session behavior. Omitting effective scope in those conditions is not simplification—it removes the fact that determines what was actually authorized.</p><h2 id="acceptance-must-not-stop-at-the-user-consented" tabindex="-1">Acceptance must not stop at “the user consented” <a class="header-anchor" href="#acceptance-must-not-stop-at-the-user-consented" aria-label="Permalink to &quot;Acceptance must not stop at “the user consented”&quot;">​</a></h2><p>A useful conformance suite should exercise four counterexamples: a persistent request normalized downward, a missing persistent key, an MCP-only decision delivered to a shell path, and policy storage failing after the decision is accepted. Every result should expose requested decision, normalized decision, effective scope and persistence outcome.</p><p>The source does not establish a complete matching, revocation, enterprise-override, concurrent-update or synchronization model, and it is not an independent security reproduction. The bounded architectural conclusion is narrower: <strong>shared approval vocabulary expresses intent; domain adapters decide whether the meaning is legal; effective scope and persistence need their own evidence.</strong></p><h3 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h3><ul><li><strong>What the source shows:</strong> the Codex protocol, implementation, and same-change tests distinguish approval outcomes and reject semantic-domain mismatches. This is checkable first-party evidence, not independent review.</li><li><strong>What the source does not establish:</strong> a complete policy matching, revocation, enterprise-override, concurrent-update, or synchronization model.</li><li><strong>What this article proposes testing:</strong> record requested scope, effective scope, and policy revision separately, then test whether the record improves auditability and failure explanation.</li></ul><p><strong>References:</strong></p><ul><li>OpenAI Codex, <a href="https://github.com/openai/codex/commit/67afc7967463282af932be1984df9e16cc55ed99" target="_blank" rel="noreferrer"><code>67afc79</code> — Use <code>ReviewDecision</code> for MCP tool approvals</a>, code commit with tests changed in the same commit boundary.</li></ul>`,30))])}const f=a(c,[["render",l]]);export{v as __pageData,f as default};
